class Cache<T> {                              // one reference: rebinding cannot fail
  #state: T;
  constructor(initial: T) { this.#state = initial; }
  commit(next: T): void { this.#state = next; }
  swapState(o: Cache<T>): void {
    [this.#state, o.#state] = [o.#state, this.#state];
  }
}
